What is the output of the following code?
int a = 17, b = 5;
printf("%d", a / b);

What is the output of the following code?
int x = 5;
int y = x++;
printf("%d %d", x, y);

What is the output of the following code?
int x = 9;
int y = ++x + 1;
printf("%d %d", x, y);

What is the output of the following code?
int i, s = 0;
for (i = 1; i <= 5; i++)
    s += i;
printf("%d", s);

What is the output of the following code?
int i;
for (i = 0; i < 10; i += 3)
    printf("%d ", i);

What is the output of the following code?
int i = 1;
while (i < 20)
    i *= 2;
printf("%d", i);

What is the output of the following code?
int k = 10;
do {
    printf("%d ", k);
    k++;
} while (k < 10);

What is the output of the following code?
int i;
for (i = 1; i <= 5; i++) {
    if (i == 3)
        break;
    printf("%d ", i);
}

What is the output of the following code?
int i;
for (i = 1; i <= 5; i++) {
    if (i == 3)
        continue;
    printf("%d ", i);
}

What is the output of the following code?
int i, j, c = 0;
for (i = 1; i <= 3; i++)
    for (j = 1; j <= i; j++)
        c++;
printf("%d", c);

What is the output of the following code?
int a[5] = {2, 4, 6, 8, 10};
printf("%d", a[1] + a[3]);

What is the output of the following code?
int a[5] = {3, 1, 4, 1, 5};
int i, n = 0;
for (i = 0; i < 5; i++)
    if (a[i] > 2)
        n++;
printf("%d", n);

What is the output of the following code?
char c = 'A';
printf("%c %d", c + 2, c + 2);

What is the output of the following code?
int n = 2;
switch (n) {
    case 1: printf("1 ");
    case 2: printf("2 ");
    case 3: printf("3 "); break;
    case 4: printf("4 ");
}

What is the output of the following code?
void swap(int a, int b) {
    int t = a;
    a = b;
    b = t;
}
int main() {
    int x = 3, y = 7;
    swap(x, y);
    printf("%d %d", x, y);
    return 0;
}

What is the output of the following code?
void inc(int *p) {
    *p = *p + 2;
}
int main() {
    int x = 4;
    inc(&x);
    inc(&x);
    printf("%d", x);
    return 0;
}

What is the output of the following code?
int fact(int n) {
    if (n <= 1)
        return 1;
    return n * fact(n - 1);
}
int main() {
    printf("%d", fact(4));
    return 0;
}

What is the output of the following code?
int f(int n) {
    if (n < 2)
        return n;
    return f(n - 1) + f(n - 2);
}
int main() {
    printf("%d", f(6));
    return 0;
}

What is the output of the following code?
void count() {
    static int n = 0;
    n++;
    printf("%d ", n);
}
int main() {
    count();
    count();
    count();
    return 0;
}

What is the output of the following code?
int x = 15;
printf("%d", x % 2 == 0 ? x / 2 : 3 * x + 1);

What is the output of the following code?
int x = 10 / 4 * 2;
printf("%d", x);

What is the output of the following code?
float f = 10 / 4;
printf("%.1f", f);

What is the output of the following code?
int x = 5;
if (x = 0)
    printf("zero");
else
    printf("nonzero");

What is the output of the following code?
int i;
for (i = 0; i < 3; i++);
printf("%d", i);

What is the output of the following code?
int n = 2345, s = 0;
while (n > 0) {
    s += n % 10;
    n /= 10;
}
printf("%d", s);

What is the output of the following code?
int n = 1250, r = 0;
while (n > 0) {
    r = r * 10 + n % 10;
    n /= 10;
}
printf("%d", r);

What is the output of the following code?
int m[3][3] = {{2, 1, 3}, {4, 5, 6}, {7, 8, 9}};
int i, s = 0;
for (i = 0; i < 3; i++)
    s += m[i][i];
printf("%d", s);

What is the output of the following code?
char s[] = "code";
printf("%c%c", s[0], s[3]);

What is the output of the following code?
char s[] = "hello";
int n = 0;
while (s[n] != '\0')
    n++;
printf("%d", n);

What is the output of the following code?
int a = 3;
a += 4;
a *= 2;
cout << a;

What is the output of the following code?
int sq(int x) {
    return x * x;
}
int main() {
    printf("%d", sq(sq(2)));
    return 0;
}

What is the output of the following code?
int x = 10;
int *p = &x;
*p = *p + 5;
printf("%d %d", x, *p);

What is the output of the following code?
int n = 5;
while (n--)
    printf("%d ", n);

What is the output of the following code?
int x = 7;
x -= 2;
x *= 3;
printf("%d", x);
